import React from 'react';

import { selectHikerAsync } from '@components/HikerSelector/hikerSelectHelper';
import PohInput, { IPohInputProps } from '@ui-kit/Input';

import nophoto from '../../../../img/nophoto.png';
import { IHiker } from '../../@types/hiking.types';

interface IHikerSelectInputProps extends Omit<IPohInputProps, 'value' | 'onChange'> {
  id_hiking: number;
  value: IHiker | null;
  onChange: (selectedHiker: IHiker) => void;
}

const HikerSelectInput: React.FC<IHikerSelectInputProps> = ({
  id_hiking,
  value,
  onChange,
  ...rest
}) => {
  return (
    <PohInput
      {...rest}
      value={value ? [value.name, value.surname].join(' ') : ''}
      readOnly={rest.readOnly || !!value}
      style={{
        backgroundImage: `url("${value ? value.photo['50'] || nophoto : nophoto}")`,
        backgroundSize: '36px',
        paddingLeft: '46px',
        backgroundRepeat: 'no-repeat',
        ...(rest.style || {}),
      }}
      onClick={() => selectHikerAsync(id_hiking, { withMe: true }).then(onChange)}
    />
  );
};

export default HikerSelectInput;
